39	/// Represents a transaction on a database connection.
40	///
41	/// ## Note
42	///
43	/// Transactions will roll back by default. Use `commit` method to explicitly
44	/// commit the transaction, or use `set_drop_behavior` to change what happens
45	/// when the transaction is dropped.
46	///
47	/// ## Example
48	///
49	/// ```rust,no_run
50	/// # use rusqlite::{Connection, Result};
51	/// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
52	/// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
53	/// fn perform_queries(conn: &mut Connection) -> Result<()> {
54	///     let tx = conn.transaction()?;
55	///
56	///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
57	///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
58	///
59	///     tx.commit()
60	/// }
61	/// ```
62	#[derive(Debug)]
63	pub struct Transaction<'conn> {
64	    conn: &'conn Connection,
65	    drop_behavior: DropBehavior,
66	    /// Set once an explicit finish has been attempted, so that the `Drop`
67	    /// impl does not try to commit or roll back a second time.
68	    finished: bool,
69	}
70	
71	/// Represents a savepoint on a database connection.
72	///
73	/// ## Note
74	///
75	/// Savepoints will roll back by default. Use `commit` method to explicitly
76	/// commit the savepoint, or use `set_drop_behavior` to change what happens
77	/// when the savepoint is dropped.
78	///
79	/// ## Example
80	///
81	/// ```rust,no_run
82	/// # use rusqlite::{Connection, Result};
83	/// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
84	/// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
85	/// fn perform_queries(conn: &mut Connection) -> Result<()> {
86	///     let sp = conn.savepoint()?;
87	///
88	///     do_queries_part_1(&sp)?; // sp causes rollback if this fails
89	///     do_queries_part_2(&sp)?; // sp causes rollback if this fails
90	///
91	///     sp.commit()
92	/// }
93	/// ```
94	#[derive(Debug)]
95	pub struct Savepoint<'conn> {
96	    conn: &'conn Connection,
97	    name: String,
98	    drop_behavior: DropBehavior,
99	    /// Set once the savepoint has been released or an explicit finish has
100	    /// been attempted, so that the `Drop` impl does not act a second time.
101	    committed: bool,
102	    /// Whether this savepoint began the transaction (i.e. it was created
103	    /// while the connection was in autocommit mode). Releasing such a
104	    /// savepoint commits the whole transaction, so cleaning up after a
105	    /// failed release requires rolling the transaction back; a nested
106	    /// savepoint may only roll back to itself and release itself.
107	    starts_transaction: bool,
108	}
109	
110	impl Transaction<'_> {
111	    /// Begin a new transaction. Cannot be nested; see `savepoint` for nested
112	    /// transactions.
113	    ///
114	    /// Even though we don't mutate the connection, we take a `&mut Connection`
115	    /// to prevent nested transactions on the same connection. For cases
116	    /// where this is unacceptable, [`Transaction::new_unchecked`] is available.
117	    #[inline]
118	    pub fn new(conn: &mut Connection, behavior: TransactionBehavior) -> Result<Transaction<'_>> {
119	        Self::new_unchecked(conn, behavior)
120	    }
121	
122	    /// Begin a new transaction, failing if a transaction is open.
123	    ///
124	    /// If a transaction is already open, this will return an error. Where
125	    /// possible, [`Transaction::new`] should be preferred, as it provides a
126	    /// compile-time guarantee that transactions are not nested.
127	    #[inline]
128	    pub fn new_unchecked(
129	        conn: &Connection,
130	        behavior: TransactionBehavior,
131	    ) -> Result<Transaction<'_>> {
132	        let query = match behavior {
133	            TransactionBehavior::Deferred => "BEGIN DEFERRED",
134	            TransactionBehavior::Immediate => "BEGIN IMMEDIATE",
135	            TransactionBehavior::Exclusive => "BEGIN EXCLUSIVE",
136	        };
137	        conn.execute_batch(query).map(move |()| Transaction {
138	            conn,
139	            drop_behavior: DropBehavior::Rollback,
140	            finished: false,
141	        })
142	    }
143	
144	    /// Starts a new [savepoint](http://www.sqlite.org/lang_savepoint.html), allowing nested
145	    /// transactions.
146	    ///
147	    /// ## Note
148	    ///
149	    /// Just like outer level transactions, savepoint transactions rollback by
150	    /// default.
151	    ///
152	    /// ## Example
153	    ///
154	    /// ```rust,no_run
155	    /// # use rusqlite::{Connection, Result};
156	    /// # fn perform_queries_part_1_succeeds(_conn: &Connection) -> bool { true }
157	    /// fn perform_queries(conn: &mut Connection) -> Result<()> {
158	    ///     let mut tx = conn.transaction()?;
159	    ///
160	    ///     {
161	    ///         let sp = tx.savepoint()?;
162	    ///         if perform_queries_part_1_succeeds(&sp) {
163	    ///             sp.commit()?;
164	    ///         }
165	    ///         // otherwise, sp will rollback
166	    ///     }
167	    ///
168	    ///     tx.commit()
169	    /// }
170	    /// ```
171	    #[inline]
172	    pub fn savepoint(&mut self) -> Result<Savepoint<'_>> {
173	        Savepoint::new_(self.conn)
174	    }
175	
176	    /// Create a new savepoint with a custom savepoint name. See `savepoint()`.
177	    #[inline]
178	    pub fn savepoint_with_name<T: Into<String>>(&mut self, name: T) -> Result<Savepoint<'_>> {
179	        Savepoint::with_name_(self.conn, name)
180	    }
181	
182	    /// Get the current setting for what happens to the transaction when it is
183	    /// dropped.
184	    #[inline]
185	    #[must_use]
186	    pub fn drop_behavior(&self) -> DropBehavior {
187	        self.drop_behavior
188	    }
189	
190	    /// Configure the transaction to perform the specified action when it is
191	    /// dropped.
192	    #[inline]
193	    pub fn set_drop_behavior(&mut self, drop_behavior: DropBehavior) {
194	        self.drop_behavior = drop_behavior;
195	    }
196	
197	    /// A convenience method which consumes and commits a transaction.
198	    #[inline]
199	    pub fn commit(mut self) -> Result<()> {
200	        self.commit_()
201	    }
202	
203	    #[inline]
204	    fn commit_(&mut self) -> Result<()> {
205	        self.conn.execute_batch("COMMIT")?;
206	        Ok(())
207	    }
208	
209	    /// A convenience method which consumes and rolls back a transaction.
210	    #[inline]
211	    pub fn rollback(mut self) -> Result<()> {
212	        self.rollback_()
213	    }
214	
215	    #[inline]
216	    fn rollback_(&mut self) -> Result<()> {
217	        self.conn.execute_batch("ROLLBACK")?;
218	        Ok(())
219	    }
220	
221	    /// Consumes the transaction, committing or rolling back according to the
222	    /// current setting (see `drop_behavior`).
223	    ///
224	    /// Functionally equivalent to the `Drop` implementation, but allows
225	    /// callers to see any errors that occur.
226	    ///
227	    /// ## Note
228	    ///
229	    /// With [`DropBehavior::Commit`], the commit is attempted only once. If
230	    /// it fails, a single best-effort rollback is attempted to return the
231	    /// connection to autocommit mode, but the original commit error is
232	    /// returned (even if the cleanup also fails), and the transaction is
233	    /// left alone when it is dropped.
234	    #[inline]
235	    pub fn finish(mut self) -> Result<()> {
236	        self.finish_()
237	    }
238	
239	    #[inline]
240	    fn finish_(&mut self) -> Result<()> {
241	        if self.finished || self.conn.is_autocommit() {
242	            return Ok(());
243	        }
244	        // An explicit finish gets a single attempt; make sure the `Drop`
245	        // impl does not commit or roll back again afterwards.
246	        self.finished = true;
247	        match self.drop_behavior() {
248	            DropBehavior::Commit => match self.commit_() {
249	                Ok(()) => Ok(()),
250	                Err(err) => {
251	                    // The commit failed, so the changes were not persisted.
252	                    // Try to roll back to leave the connection usable, but
253	                    // always report the original commit error, even if the
254	                    // cleanup fails. SQLite may already have ended the
255	                    // transaction itself (e.g. when an authorizer denied the
256	                    // commit), in which case there is nothing to clean up.
257	                    if !self.conn.is_autocommit() {
258	                        let _ = self.rollback_();
259	                    }
260	                    Err(err)
261	                }
262	            },
263	            DropBehavior::Rollback => self.rollback_(),
264	            DropBehavior::Ignore => Ok(()),
265	            DropBehavior::Panic => panic!("Transaction dropped unexpectedly."),
266	        }
267	    }
268	}
