333	    /// Get the current setting for what happens to the savepoint when it is
334	    /// dropped.
335	    #[inline]
336	    #[must_use]
337	    pub fn drop_behavior(&self) -> DropBehavior {
338	        self.drop_behavior
339	    }
340	
341	    /// Configure the savepoint to perform the specified action when it is
342	    /// dropped.
343	    #[inline]
344	    pub fn set_drop_behavior(&mut self, drop_behavior: DropBehavior) {
345	        self.drop_behavior = drop_behavior;
346	    }
347	
348	    /// A convenience method which consumes and commits a savepoint.
349	    #[inline]
350	    pub fn commit(mut self) -> Result<()> {
351	        self.commit_()
352	    }
353	
354	    #[inline]
355	    fn commit_(&mut self) -> Result<()> {
356	        let sql = cmd("RELEASE", false, self.name.as_str())?;
357	        self.conn.execute_batch(sql.as_str())?;
358	        self.committed = true;
359	        Ok(())
360	    }
361	
362	    /// A convenience method which rolls back a savepoint.
363	    ///
364	    /// ## Note
365	    ///
366	    /// Unlike `Transaction`s, savepoints remain active after they have been
367	    /// rolled back, and can be rolled back again or committed.
368	    #[inline]
369	    pub fn rollback(&mut self) -> Result<()> {
370	        let sql = cmd("ROLLBACK", true, self.name.as_str())?;
371	        self.conn.execute_batch(sql.as_str())
372	    }
373	
374	    /// Consumes the savepoint, committing or rolling back according to the
375	    /// current setting (see `drop_behavior`).
376	    ///
377	    /// Functionally equivalent to the `Drop` implementation, but allows
378	    /// callers to see any errors that occur.
379	    ///
380	    /// ## Note
381	    ///
382	    /// With [`DropBehavior::Commit`], the release is attempted only once. If
383	    /// it fails, a single best-effort cleanup is attempted (rolling back the
384	    /// transaction if this savepoint began it, or rolling back to and
385	    /// releasing this savepoint if it is nested), but the original release
386	    /// error is returned (even if the cleanup also fails), and the savepoint
387	    /// is left alone when it is dropped.
388	    #[inline]
389	    pub fn finish(mut self) -> Result<()> {
390	        self.finish_()
391	    }
392	
393	    #[inline]
394	    fn finish_(&mut self) -> Result<()> {
395	        if self.committed {
396	            return Ok(());
397	        }
398	        // An explicit finish gets a single attempt; make sure the `Drop`
399	        // impl does not release or roll back again afterwards.
400	        self.committed = true;
401	        match self.drop_behavior() {
402	            DropBehavior::Commit => match self.commit_() {
403	                Ok(()) => Ok(()),
404	                Err(err) => {
405	                    // The release failed, so the savepoint is still active.
406	                    // Clean up according to the savepoint's scope, but always
407	                    // report the original release error, even if the cleanup
408	                    // fails.
409	                    self.cleanup_after_failed_commit();
410	                    Err(err)
411	                }
412	            },
413	            DropBehavior::Rollback => self.rollback().and_then(|()| self.commit_()),
414	            DropBehavior::Ignore => Ok(()),
415	            DropBehavior::Panic => panic!("Savepoint dropped unexpectedly."),
416	        }
417	    }
418	
419	    /// Best-effort cleanup after a failed release, limited to the changes
420	    /// this savepoint is responsible for. The outcome is ignored: callers
421	    /// report the release error, and a failed cleanup leaves the still
422	    /// active transaction or savepoint for the caller to resolve.
423	    #[inline]
424	    fn cleanup_after_failed_commit(&mut self) {
425	        if self.conn.is_autocommit() {
426	            // SQLite already ended the transaction on its own; there is
427	            // nothing left to clean up.
428	            return;
429	        }
430	        if self.starts_transaction {
431	            // Releasing this savepoint would have committed the whole
432	            // transaction, so roll the transaction back to undo the changes
433	            // and return the connection to autocommit mode.
434	            let _ = self.conn.execute_batch("ROLLBACK");
435	        } else {
436	            // Nested savepoint: undo only the changes made since it was
437	            // established, then release it, preserving the outer
438	            // transaction. If the rollback is not possible, do not release
439	            // either, as that would keep the changes.
440	            let _ = self.rollback().and_then(|()| self.commit_());
441	        }
442	    }
443	}
