486	impl Connection {
487	    /// Begin a new transaction with the default behavior (DEFERRED).
488	    ///
489	    /// The transaction defaults to rolling back when it is dropped. If you
490	    /// want the transaction to commit, you must call
491	    /// [`commit`](Transaction::commit) or
492	    /// [`set_drop_behavior(DropBehavior::Commit)`](Transaction::set_drop_behavior).
493	    ///
494	    /// ## Example
495	    ///
496	    /// ```rust,no_run
497	    /// # use rusqlite::{Connection, Result};
498	    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
499	    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
500	    /// fn perform_queries(conn: &mut Connection) -> Result<()> {
501	    ///     let tx = conn.transaction()?;
502	    ///
503	    ///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
504	    ///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
505	    ///
506	    ///     tx.commit()
507	    /// }
508	    /// ```
509	    ///
510	    /// # Failure
511	    ///
512	    /// Will return `Err` if the underlying SQLite call fails.
513	    #[inline]
514	    pub fn transaction(&mut self) -> Result<Transaction<'_>> {
515	        Transaction::new(self, self.transaction_behavior)
516	    }
517	
518	    /// Begin a new transaction with a specified behavior.
519	    ///
520	    /// See [`transaction`](Connection::transaction).
521	    ///
522	    /// # Failure
523	    ///
524	    /// Will return `Err` if the underlying SQLite call fails.
525	    #[inline]
526	    pub fn transaction_with_behavior(
527	        &mut self,
528	        behavior: TransactionBehavior,
529	    ) -> Result<Transaction<'_>> {
530	        Transaction::new(self, behavior)
531	    }
532	
533	    /// Begin a new transaction with the default behavior (DEFERRED).
534	    ///
535	    /// Attempt to open a nested transaction will result in a SQLite error.
536	    /// `Connection::transaction` prevents this at compile time by taking `&mut
537	    /// self`, but `Connection::unchecked_transaction()` may be used to defer
538	    /// the checking until runtime.
539	    ///
540	    /// See [`Connection::transaction`] and [`Transaction::new_unchecked`]
541	    /// (which can be used if the default transaction behavior is undesirable).
542	    ///
543	    /// ## Example
544	    ///
545	    /// ```rust,no_run
546	    /// # use rusqlite::{Connection, Result};
547	    /// # use std::rc::Rc;
548	    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
549	    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
550	    /// fn perform_queries(conn: Rc<Connection>) -> Result<()> {
551	    ///     let tx = conn.unchecked_transaction()?;
552	    ///
553	    ///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
554	    ///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
555	    ///
556	    ///     tx.commit()
557	    /// }
558	    /// ```
559	    ///
560	    /// # Failure
561	    ///
562	    /// Will return `Err` if the underlying SQLite call fails. The specific
563	    /// error returned if transactions are nested is currently unspecified.
564	    pub fn unchecked_transaction(&self) -> Result<Transaction<'_>> {
565	        Transaction::new_unchecked(self, self.transaction_behavior)
566	    }
