618	    /// Set the default transaction behavior for the connection.
619	    ///
620	    /// ## Note
621	    ///
622	    /// This will only apply to transactions initiated by [`transaction`](Connection::transaction)
623	    /// or [`unchecked_transaction`](Connection::unchecked_transaction).
624	    ///
625	    /// ## Example
626	    ///
627	    /// ```rust,no_run
628	    /// # use rusqlite::{Connection, Result, TransactionBehavior};
629	    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
630	    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
631	    /// fn perform_queries(conn: &mut Connection) -> Result<()> {
632	    ///     conn.set_transaction_behavior(TransactionBehavior::Immediate);
633	    ///
634	    ///     let tx = conn.transaction()?;
635	    ///
636	    ///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
